fn insert_action(p:&mut RowWriter<'_,'_>,table:&str,parent:i64,n:usize,a:&LoadCaseActions)->Result<(), ValueError>{p.insert_float(table,&[Cell::Integer(parent),ordinal(n)?,Cell::Text(&a.id),Cell::Text(action_kind_text(a.kind)),Cell::Text(psi_category_text(a.category)),Cell::Text(action_source_text(a.source)),Cell::Real(a.g_k_line),Cell::Real(a.q_k_line),Cell::Real(a.point_force),Cell::Real(a.m_k),Cell::Real(a.n_k),Cell::Real(a.v_k),Cell::Real(a.t_k),Cell::Real(a.v_k_punch)],ACTION)?;Ok(())}
