   let mut longitudinal=Vec::new();for a in ordered(bars.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?{longitudinal.push(BarLayer{id:text(a,3,c)?,diameter:a.real(4)?,count:u32_value(a,5)?,position:read_bar_position(&text(a,6,c)?)?,anchorage_length:a.real(7)?,lap_length:a.real(8)?,bond_condition:read_bond_condition(&text(a,9,c)?)?,aggregate_size:a.real(10)?,lap_share:a.real(11)?});}
